        LocalTime base = LocalTime.of(11, 30);
        assertEquals(LocalTime.of(11, 30), Seconds.of(0).addTo(base));
        assertEquals(LocalTime.of(11, 30, 6), Seconds.of(6).addTo(base));
    }

