    /**
     * Returns a string representation of the number of seconds.
     * This will be in the format 'PTnS' where n is the number of seconds.
     *
     * @return the number of seconds in ISO-8601 string format
     */
    @Override
    @ToString
    public String toString() {
        return "PT" + seconds + "S";
    }

}
